<template><section class="integration-atlas"><h3>X6 · Complete original Core feature atlas</h3><p>Raw source records, before any gene matching. All finite values enter the histogram and exact ECDF; zeros and missing records are counted separately.</p><div class="integration-toolbar"><label>Layer <select v-model="omics"><option value="genome">Genome</option><option value="transcriptome">RNA</option><option value="proteome">Protein</option></select></label><label>Field name / ID <input v-model="search" /></label><label>Family <select v-model="family"><option value="">All families</option><option v-for="k in families" :key="k">{{ k }}</option></select></label><a :href="download">All {{ omics }} exact frequencies CSV</a></div><p v-if="error" role="alert">{{ error }}</p><p>{{ result?.total??'…' }} fields · page {{ page }} / {{ Math.ceil((result?.total||0)/6) }}</p><div class="integration-grid"><article v-for="p in result?.items||[]" :key="p.field" class="integration-field" :data-integration-field="p.field"><h4>{{ p.field_id }} · {{ p.field }}</h4><div class="integration-toolbar"><button class="btn subtle" @click="save(p,'svg')">SVG</button><button class="btn subtle" @click="save(p,'png')">PNG 4×</button><a :href="fieldDownload(p.field)">Exact frequencies CSV</a></div><p>{{ p.source_unit }} · source {{ p.n_source }} · finite {{ p.n_valid }} · missing {{ p.n_missing }} · zeros {{ p.n_zero }} · unique {{ p.n_unique }}</p><div class="integration-scroll"><div style="min-width:420px"><EChart :option="profileOption(p)" :height="320" :auto-loading="false" :show-exports="false" /></div></div></article></div><div class="integration-toolbar"><button class="btn subtle" :disabled="page===1" @click="page--">Previous fields</button><button class="btn subtle" :disabled="page*6>=result?.total" @click="page++">Next fields</button></div></section></template>
<script setup>
import {ref,watch,computed,onMounted} from 'vue';import {exportIntegration} from '../../utils/integrationExport';import EChart from '../EChart.vue';import {integrationDistribution} from '../../utils/integrationCharts';import {integrationExport} from '../../api/integrationVisuals'
const props=defineProps({context:Object,speciesId:String});const omics=ref('genome'),search=ref(''),family=ref(''),page=ref(1),result=ref(null),error=ref('');let seq=0
const families=computed(()=>[...new Set((props.context.manifest.value?.catalog?.[omics.value]||[]).map(r=>r.family))].sort())
async function load(){const s=++seq,id=props.speciesId;try{const r=await props.context.get('fields/',{omics:omics.value,search:search.value,family:family.value,page:page.value,page_size:6});if(s===seq&&id===props.speciesId){result.value=r;error.value=''}}catch(e){if(s===seq)error.value=e.message}}
watch([omics,search,family],()=>{page.value=1;load()});watch(page,load);watch(()=>props.context.manifest.value?.artifact_version,()=>{result.value=null;load()});onMounted(load)
const download=computed(()=>integrationExport(props.speciesId,{...props.context.params(),kind:'field_profiles',omics:omics.value}))
function fieldDownload(field){return integrationExport(props.speciesId,{...props.context.params(),kind:'field_profiles',omics:omics.value,field})}
async function save(p,format){try{const layer=p.omics||({G:'genome',T:'transcriptome',P:'proteome'}[p.field_id?.[0]])||omics.value,source=props.context.manifest.value.source_audit?.[layer]?.sha256||props.context.manifest.value.source_hash;const o=profileOption(p);o.graphic=[{type:'text',left:12,bottom:4,style:{text:`${props.speciesId} · ${p.field_id} · n_source=${p.n_source} · n_valid=${p.n_valid}\n${props.context.manifest.value.method_version} · ${props.context.manifest.value.artifact_version}\nCore SHA ${source.slice(0,32)}`,fontSize:10,lineHeight:13,fill:'#556775'}}];await exportIntegration(o,{format,title:`${p.field_id} · ${p.field} (${p.source_unit})`,name:`${props.speciesId}_${p.field_id}_${props.context.manifest.value.artifact_version}`,height:350})}catch(e){error.value=e.message}}
function profileOption(p){const o=integrationDistribution(p,p.source_unit,true);o.grid.left=78;o.grid.right=78;o.xAxis.nameGap=25;return o}
</script>
